let _settingsSaveWarningShown = false;
let browserWorkflowLibrary = [];
let browserSponsorExemptions = {};

function normalizeBrowserSponsorExemptions(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const records = [];
  for (const [rawKey, rawRecord] of Object.entries(value)) {
    const mediaKey = String(rawKey || '').trim().slice(0, 512);
    if (!mediaKey) continue;
    const rawIds = Array.isArray(rawRecord) ? rawRecord : rawRecord?.ids;
    if (!Array.isArray(rawIds)) continue;
    const ids = [...new Set(rawIds.map((id) => String(id || '').trim().slice(0, 256)).filter(Boolean))]
      .slice(0, 200);
    if (!ids.length) continue;
    const updatedAt = Number.isFinite(Number(rawRecord?.updatedAt))
      ? Math.max(0, Number(rawRecord.updatedAt)) : 0;
    records.push([mediaKey, { ids, updatedAt }]);
  }
  records.sort((left, right) => right[1].updatedAt - left[1].updatedAt);
  return Object.fromEntries(records.slice(0, 100));
}

function secretSettingValue(id) {
  const control = $(id);
  const value = control?.value.trim() || '';
  // Kasa açılamadığı için boş gelen alan, kullanıcının silme isteği değildir.
  return (value || control?.dataset.secretEdited === 'true') ? value : undefined;
}
function secretSettingPatch(id, key = 'apiKey') {
  const value = secretSettingValue(id);
  return value === undefined ? {} : { [key]: value };
}

const providerApiKeyProfiles = { translate: {}, manga: {} };
const activeProviderCredentialScopes = { translate: '', manga: '' };
const providerApiKeyProfilesEdited = { translate: false, manga: false };
let providerModelProfiles = {};

function providerCredentialScopeFor(kind) {
  const api = window.WhisperProviderApiKeys;
  if (!api) return '';
  const preset = $(`${kind}EndpointPreset`)?.value || '';
  const customBaseUrl = $(`${kind}BaseUrl`)?.value || '';
  if (kind === 'manga' && preset === 'inherit') {
    return api.providerCredentialScope(preset, customBaseUrl,
      $('translateEndpointPreset')?.value || '', $('translateBaseUrl')?.value || '');
  }
  return api.providerCredentialScope(preset, customBaseUrl);
}

function rememberVisibleProviderApiKey(kind) {
  const api = window.WhisperProviderApiKeys;
  const control = $(`${kind}ApiKey`);
  const scope = activeProviderCredentialScopes[kind] || providerCredentialScopeFor(kind);
  if (!api || !control || !scope) return;
  const before = api.serializeProviderKeyProfiles(providerApiKeyProfiles[kind]);
  providerApiKeyProfiles[kind] = api.updateProviderKeyProfile(
    providerApiKeyProfiles[kind], scope, control.value, control.dataset.secretEdited === 'true');
  if (api.serializeProviderKeyProfiles(providerApiKeyProfiles[kind]) !== before) {
    providerApiKeyProfilesEdited[kind] = true;
  }
}

function activateProviderApiKey(kind, { markActiveEdited = true } = {}) {
  const api = window.WhisperProviderApiKeys;
  const control = $(`${kind}ApiKey`);
  if (!api || !control) return;
  rememberVisibleProviderApiKey(kind);
  const scope = providerCredentialScopeFor(kind);
  activeProviderCredentialScopes[kind] = scope;
  control.value = api.providerKeyForScope(providerApiKeyProfiles[kind], scope);
  control.dataset.secretEdited = markActiveEdited ? 'true' : 'false';
}

function initializeProviderApiKeyState(kind, settingsGroup = {}) {
  const api = window.WhisperProviderApiKeys;
  const control = $(`${kind}ApiKey`);
  if (!api || !control) return;
  providerApiKeyProfiles[kind] = api.normalizeProviderKeyProfiles(settingsGroup.apiKeyProfiles);
  const scope = providerCredentialScopeFor(kind);
  const legacyKey = typeof settingsGroup.apiKey === 'string' ? settingsGroup.apiKey.trim() : '';
  if (scope && legacyKey && !api.providerKeyForScope(providerApiKeyProfiles[kind], scope)) {
    providerApiKeyProfiles[kind] = api.updateProviderKeyProfile(
      providerApiKeyProfiles[kind], scope, legacyKey, true);
    providerApiKeyProfilesEdited[kind] = true;
  }
  activeProviderCredentialScopes[kind] = scope;
  control.value = api.providerKeyForScope(providerApiKeyProfiles[kind], scope) || legacyKey;
  control.dataset.secretEdited = 'false';
}

function providerApiKeyProfilesPatch(kind) {
  const api = window.WhisperProviderApiKeys;
  if (!api || !providerApiKeyProfilesEdited[kind]) return {};
  const serialized = api.serializeProviderKeyProfiles(providerApiKeyProfiles[kind]);
  return { apiKeyProfiles: serialized === '{}' ? '' : serialized };
}

function providerSettingText(value) {
  return window.UiLocale?.t ? window.UiLocale.t(String(value || '')) : String(value || '');
}

function initializeProviderModelProfiles(settingsGroup = {}) {
  const api = window.WhisperProviderModels;
  providerModelProfiles = api
    ? api.normalizeProviderModelProfiles(settingsGroup.modelProfiles)
    : {};
  renderProviderModelChoices();
}

function providerModelProfilesValue() {
  const api = window.WhisperProviderModels;
  return api ? api.serializeProviderModelProfiles(providerModelProfiles) : '';
}

function renderProviderModelChoices(preferred = $('translateModel')?.value.trim() || '') {
  const api = window.WhisperProviderModels;
  const select = $('translateSavedModel');
  if (!api || !select) return;
  const scope = providerCredentialScopeFor('translate');
  const models = api.providerModelsForScope(providerModelProfiles, scope);
  select.replaceChildren();
  const placeholder = document.createElement('option');
  placeholder.value = '';
  placeholder.textContent = providerSettingText('Kayıtlı özel model yok');
  select.appendChild(placeholder);
  for (const model of models) {
    const option = document.createElement('option');
    option.value = model;
    option.textContent = model;
    select.appendChild(option);
  }
  select.value = models.includes(preferred) ? preferred : '';
  $('translateRemoveModel')?.toggleAttribute('disabled', !select.value);
}

function resetTranslationProviderProbe() {
  const output = $('translateProbeStatus');
  if (!output) return;
  output.dataset.state = 'idle';
  output.textContent = providerSettingText('Henüz test edilmedi.');
}

function translationProbeMessage(result) {
  const messages = {
    authentication: 'API anahtarı reddedildi.',
    model_unavailable: 'Seçili model bu sağlayıcıda bulunamadı.',
    rate_limit: 'Sağlayıcının istek sınırına ulaşıldı.',
    provider_unavailable: 'Sağlayıcı geçici olarak kullanılamıyor.',
    endpoint_not_found: 'Endpoint bulunamadı veya uyumlu değil.',
    timeout: 'İstek zaman aşımına uğradı.',
    network: 'Sağlayıcıya ağ bağlantısı kurulamadı.',
    request_rejected: 'Sağlayıcı test isteğini reddetti.',
    invalid_response: 'Sağlayıcı yanıtı geçersiz.',
    invalid_config: 'Önce API anahtarı ve model girin.',
  };
  return providerSettingText(messages[result?.code] || 'Test isteği gönderilemedi.');
}

async function testSelectedTranslationProvider() {
  const button = $('translateProbeBtn');
  const output = $('translateProbeStatus');
  if (!button || !output || !window.api.testTranslationProvider) return;
  const model = $('translateModel')?.value.trim() || '';
  const apiKey = $('translateApiKey')?.value.trim() || '';
  if (!model) {
    output.dataset.state = 'error';
    output.textContent = providerSettingText('Önce API anahtarı ve model girin.');
    return;
  }
  button.disabled = true;
  output.dataset.state = 'testing';
  output.textContent = providerSettingText('Sağlayıcı test ediliyor…');
  try {
    const result = await window.api.testTranslationProvider({
      endpointPreset: $('translateEndpointPreset')?.value || '',
      customBaseUrl: $('translateBaseUrl')?.value.trim() || '',
      model,
      apiKey,
    });
    const latency = Number(result?.latencyMs) > 0 ? ` · ${Math.round(result.latencyMs)} ms` : '';
    const status = Number(result?.status) > 0 ? ` · HTTP ${Math.trunc(result.status)}` : '';
    output.dataset.state = result?.ok ? 'success' : 'error';
    output.textContent = (result?.ok
      ? providerSettingText('Bağlantı ve model çalışıyor.')
      : translationProbeMessage(result)) + status + latency;
  } catch (_) {
    output.dataset.state = 'error';
    output.textContent = providerSettingText('Test isteği gönderilemedi.');
  } finally {
    button.disabled = false;
  }
}

document.addEventListener('change', (event) => {
  if (['hfToken', 'translateApiKey', 'mangaApiKey', 'llmApiKey'].includes(event.target.id)) {
    event.target.dataset.secretEdited = 'true';
  }
}, true);
async function saveAppSettings() {
  let saved;
  try {
    saved = await window.api.saveSettings(appSettingsPayload());
  } catch (_) {
    saved = false;
  }
  if (saved === false || saved?.ok === false) {
    if (!_settingsSaveWarningShown) {
      _settingsSaveWarningShown = true;
      const message = saved?.error
        || 'Ayarlar güvenli biçimde kaydedilemedi. Güvenli anahtar deposunu ve disk erişimini kontrol edin.';
      logLine(message, 'error');
      if (player.workspaceMode === 'browser') {
        setBrowserSignal(message, false,
          { priority: 100, holdMs: 8000 });
      }
    }
    return false;
  }
  _settingsSaveWarningShown = false;
  providerApiKeyProfilesEdited.translate = false;
  providerApiKeyProfilesEdited.manga = false;
  for (const id of ['hfToken', 'translateApiKey', 'mangaApiKey', 'llmApiKey']) {
    if ($(id)) $(id).dataset.secretEdited = 'false';
  }
  return true;
}

function appSettingsPayload() {
  rememberVisibleProviderApiKey('translate');
  rememberVisibleProviderApiKey('manga');
  return {
    glossary,
    ...secretSettingPatch('hfToken', 'hfToken'),
    inputDir: state.inputDir || '',
    outputDir: state.outputDir || '',
    preset: $('presetSelect').value,
    presetReference: _presetReference,
    watchDir: state.watchDir || '',
    translate: {
      ...secretSettingPatch('translateApiKey'),
      ...providerApiKeyProfilesPatch('translate'),
      endpointPreset: $('translateEndpointPreset') ? $('translateEndpointPreset').value : '',
      customBaseUrl: $('translateBaseUrl') ? $('translateBaseUrl').value.trim() : '',
      model: $('translateModel') ? $('translateModel').value.trim() : '',
      modelProfiles: providerModelProfilesValue(),
    },
    manga: {
      ...secretSettingPatch('mangaApiKey'),
      ...providerApiKeyProfilesPatch('manga'),
      endpointPreset: $('mangaEndpointPreset') ? $('mangaEndpointPreset').value : 'inherit',
      customBaseUrl: $('mangaBaseUrl') ? $('mangaBaseUrl').value.trim() : '',
      model: $('mangaModel') ? $('mangaModel').value.trim() : '',
      targetLanguage: $('browserMangaTarget')?.value || 'tr',
      workers: Number($('browserMangaWorkers')?.value) || 2,
      maxImages: Number($('browserMangaMaxImages')?.value) || 48,
      fontScale: (Number($('browserMangaFontScale')?.value) || 100) / 100,
      fontFamily: $('browserMangaFont')?.value || 'comic',
      autoTranslate: !!$('browserMangaAuto')?.checked,
      verticalText: !!$('browserMangaVertical')?.checked,
      sfxStyle: $('browserMangaSfx')?.checked !== false,
    },
    llm: {
      ...secretSettingPatch('llmApiKey'),
      endpointPreset: $('llmEndpointPreset') ? $('llmEndpointPreset').value : '',
      customBaseUrl: $('llmBaseUrl') ? $('llmBaseUrl').value.trim() : '',
      model: $('llmModel') ? $('llmModel').value.trim() : '',
    },
    ui: collectUiSettings(),
    playerPositions: player.positions,
    browserSponsorExemptions: normalizeBrowserSponsorExemptions(browserSponsorExemptions),
    browserWorkflows: window.BrowserWorkflowRecorder
      ? window.BrowserWorkflowRecorder.normalizeWorkflowLibrary(browserWorkflowLibrary) : [],
  };
}

